// Same default-on consent pattern as Smart Energy Finance.
if (String(env.get("SEND_BIP") || "true").toLowerCase() !== "true") {
    node.status({fill:"grey",shape:"ring",text:"BIP disabled by user"});
    return null;
}
const installId=String(env.get("SMART_JKBMS_INSTALL_ID") || "").trim();
if (!/^[a-f0-9]{8}(?:-[a-f0-9]{4}){3}-[a-f0-9]{12}$/i.test(installId)) {
    node.status({fill:"red",shape:"ring",text:"BIP install ID unavailable"});
    node.warn("JK-BMS BIP: installation identifier is missing or invalid");
    return null;
}
msg.bipInstallId=installId;
return msg;

// Do not report HTTP 302 as success: Google may return an error JSON.
const http=Number(msg.statusCode) || 0;
let data=msg.payload;
if (typeof data === "string") {
    try { data=JSON.parse(data); }
    catch (_) { data=null; }
}
const ok=http===200 && data && data.success===true &&
    String(data.module || "").toLowerCase()==="jkbms" &&
    ["created","updated"].includes(String(data.status || ""));
const status=ok ? String(data.status) : "not confirmed";
const reason=(data && data.error) ? String(data.error).slice(0,160) :
    (msg.bipError || ("HTTP "+http));
node.status({fill:ok?"green":"red",shape:ok?"dot":"ring",
    text:ok?"Google JK-BMS "+status:"BIP "+reason});
if (!ok) node.warn("JK-BMS BIP not confirmed: "+reason);
// Send only a sanitized result to any user-attached Debug nodes.
msg.payload={success:!!ok, module:"jkbms", status, http_status:http,
    reason:ok?"":reason};
delete msg.bipInstallId;
delete msg.googleQuery;
delete msg.headers;
delete msg.url;
return msg;

// The add-on is built for Home Assistant OS; same BIP convention as Finance.
// One installation ID counts an installation, regardless of its BMS count.
msg.telemetry={bipBase:1,environment:"Home Assistant OS"};
node.status({fill:"blue",shape:"dot",text:"HAOS / free"});
return msg;

// Finance-compatible collector payload, without battery or location details.
const version=String(env.get("SMART_JKBMS_VERSION") || "").trim();
if (!msg.bipInstallId || !version) {
    node.status({fill:"red",shape:"ring",text:"BIP ID/version missing"});
    return null;
}
msg.payload={
    module:"jkbms",
    install_id:msg.bipInstallId,
    bip:String((msg.telemetry||{}).bipBase || 1)+"0",
    version:version,
    country:"",region:"",city:"",lat:"",lon:""
};
msg.headers={"Content-Type":"application/json"};
msg.followRedirects=false; // Finance: never auto-repeat POST on redirect.
delete msg.url;
delete msg.method;
node.status({fill:"blue",shape:"dot",text:"v"+version+" / BIP "+msg.payload.bip});
return msg;

// Apps Script ContentService normally returns 302/303 to a JSON GET endpoint.
// Finance deliberately does NOT follow the redirect with another POST.
// Follow it manually as GET, then read {success, status} from Google's JSON.
const status=Number(msg.statusCode)||0;
if (status===302 || status===303) {
    const headers=msg.headers||{};
    const location=String(headers.location || headers.Location || "");
    const match=/^https:\/\/script\.googleusercontent\.com\/macros\/echo\?([A-Za-z0-9._~!$&'()*+,;=:%-]+)$/.exec(location);
    if (!match) {
        msg.bipError="Google redirect missing/invalid: confirm Apps Script deployment";
        return [null,msg];
    }
    msg.googleQuery=match[1];
    msg.payload="";
    msg.headers={};
    delete msg.method;
    delete msg.url;
    msg.followRedirects=true;
    return [msg,null];
}
return [null,msg];
